// generated by gemini-3.5-flash-lite for PR #6030 (round 0): file_input_binary_bson
// intent: Test BSON binary format reading from a FILE stream.
#include <nlohmann/json.hpp>
#include <cstdio>
#include <iostream>
int main() {
    std::FILE* f = std::tmpfile();
    if (!f) return 0;
    nlohmann::json j = {{"key", "value"}};
    std::vector<uint8_t> v = nlohmann::json::to_bson(j);
    std::fwrite(v.data(), 1, v.size(), f);
    std::rewind(f);
    try {
        auto j2 = nlohmann::json::from_bson(f);
        std::cout << j2.dump() << std::endl;
    } catch (const std::exception& e) {
        std::cout << "Exception: " << e.what() << std::endl;
    }
    std::fclose(f);
}
